cd /tmp/sv-59c8f2010e434a1c92b3a2ee169621b0/moderate-version-conflicts && python3 -c "
import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract(data):
    result = {}
    for p in data.get('projects', []):
        name = p['path'].split('/')[-1]
        for fw in p.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                key = (name, pkg['id'])
                result[key] = pkg.get('resolvedVersion', pkg.get('requestedVersion', '?'))
    return result

b = extract(baseline)
a = extract(after)

print('CHANGES:')
for key in sorted(set(b.keys()) | set(a.keys())):
    bv = b.get(key, 'N/A')
    av = a.get(key, 'N/A')
    if bv != av:
        print(f'  {key[0]} | {key[1]} | {bv} -> {av}')

print('UNCHANGED:')
for key in sorted(set(b.keys()) & set(a.keys())):
    if b[key] == a[key]:
        print(f'  {key[0]} | {key[1]} | {b[key]}')
"

